import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Keynote- Welcome & State of the Cephalopod Part I - Josh Durgin, Neha Ojha, and Dan van der Ster","description":"","frontmatter":{"title":"Keynote- Welcome & State of the Cephalopod Part I - Josh Durgin, Neha Ojha, and Dan van der Ster","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","分布式存储","社区发展","开源协作","技术创新"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Welcome_State_of_the_Cephalopod_Part_I_-_Josh_Durgin_Neha_Ojha_and_Dan_van_der_Ster.md","filePath":"posts/2025/Keynote_-_Welcome_State_of_the_Cephalopod_Part_I_-_Josh_Durgin_Neha_Ojha_and_Dan_van_der_Ster.md","lastUpdated":1780459816000}'),_={name:"posts/2025/Keynote_-_Welcome_State_of_the_Cephalopod_Part_I_-_Josh_Durgin_Neha_Ojha_and_Dan_van_der_Ster.md"};function n(l,e,h,i,s,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="ceph-北美社区会议纪要-sephlacon-north-america-2023-开幕式" tabindex="-1">Ceph 北美社区会议纪要：Sephlacon North America 2023 开幕式 <a class="header-anchor" href="#ceph-北美社区会议纪要-sephlacon-north-america-2023-开幕式" aria-label="Permalink to &quot;Ceph 北美社区会议纪要：Sephlacon North America 2023 开幕式&quot;">​</a></h3><h4 id="_1-开场与致谢" tabindex="-1"><strong>1. 开场与致谢</strong> <a class="header-anchor" href="#_1-开场与致谢" aria-label="Permalink to &quot;**1. 开场与致谢**&quot;">​</a></h4><ul><li>会议在加拿大温哥华举行，主办方对传统原住民领地（Musquam、Squamish、Swit 民族）表示敬意。</li><li>Ceph 执行委员会成员（Niha Oja、Dan、Josh）欢迎参会者，强调此次会议是北美首次 Sephlacon，标志着 Ceph 社区的全球化扩展。</li></ul><h4 id="_2-会议组织与赞助" tabindex="-1"><strong>2. 会议组织与赞助</strong> <a class="header-anchor" href="#_2-会议组织与赞助" aria-label="Permalink to &quot;**2. 会议组织与赞助**&quot;">​</a></h4><ul><li>感谢铂金赞助商 45 Drives、Bloomberg、IBM，以及黄金赞助商 Clyo 和白银赞助商 Canonical、OS Nexs。</li><li>提供Wi-Fi密码、场地地图等信息，并介绍活动安排，包括3个并行演讲流、赞助商展示厅、Booth Crawl 社交活动等。</li></ul><h4 id="_3-ceph-项目进展与数据" tabindex="-1"><strong>3. Ceph 项目进展与数据</strong> <a class="header-anchor" href="#_3-ceph-项目进展与数据" aria-label="Permalink to &quot;**3. Ceph 项目进展与数据**&quot;">​</a></h4><ul><li>社区贡献者超过1400人，累计提交156K+次代码变更，代码行数超过700K行。</li><li>Linux Foundation Insights 数据显示，GitHub Star 数和 Commit 活动持续上升，Ceph 集群总容量从1 EB增长至近2 EB。</li><li>版本发布计划：当前版本 Tentacle（预计2023年底发布），后续版本 Umbrella（2026年），支持 LTS 策略。</li></ul><h4 id="_4-社区动态与未来计划" tabindex="-1"><strong>4. 社区动态与未来计划</strong> <a class="header-anchor" href="#_4-社区动态与未来计划" aria-label="Permalink to &quot;**4. 社区动态与未来计划**&quot;">​</a></h4><ul><li>介绍新任社区经理 Anthony Middleton，他将推动区域活动（如 Ceph Days）。</li><li>强调开源协作精神，计划明年更多区域性活动以扩展社区。</li></ul><h4 id="_5-后续行动" tabindex="-1"><strong>5. 后续行动</strong> <a class="header-anchor" href="#_5-后续行动" aria-label="Permalink to &quot;**5. 后续行动**&quot;">​</a></h4><ul><li>鼓励参会者通过注册台联系会务组解决疑问。</li><li>介绍技术议程，包括 IBM 主题演讲和首场 Keynote。</li></ul><p>总结中保留了以下关键词：Ceph、Telemetry、LTS（Long-Term Support）、Commits、Contributors、CRUSH algorithm、RADOS、OSD、MON、PG、librados、CephFS、RBD、RGW、erasure coding、replication。</p><p>此次会议旨在展示 Ceph 生态增长，促进技术交流与社区协作，推动分布式存储在多云和容器化场景的应用。</p>',13)])])}const u=a(_,[["render",n]]);export{c as __pageData,u as default};
